    private Double calcularValorParcela(Double totalFinal, FormaPagamento formaPagamento, Integer parcelas) {
        if (formaPagamento == FormaPagamento.CARTAO && parcelas > 3) {
            double taxaMensal = 0.0199;
            double parcela = totalFinal * taxaMensal / (1.0 - Math.pow(1.0 + taxaMensal, -parcelas));
            return parcela;
        }
        return totalFinal / parcelas;
    }

    private Double calcularCredito(NivelClube nivelClube, Double subtotalProdutos) {
        return nivelClube.calcularCredito(subtotalProdutos);
    }
}

